"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import Image from "next/image";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ScanEntry } from "@/types/menu";

// Prerender-disabled: requires active session
export const dynamic = "force-dynamic";

interface CompareState {
  scan1: ScanEntry | null;
  scan2: ScanEntry | null;
  loading: boolean;
  error: string | null;
}

export default function ComparePage() {
  const router = useRouter();
  const { status } = useSession();
  const [state, setState] = useState<CompareState>({
    scan1: null,
    scan2: null,
    loading: true,
    error: null,
  });

  useEffect(() => {
    if (status === "unauthenticated") {
      router.push("/auth/login");
    }
  }, [status, router]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const scanId1 = params.get("scanId1");
    const scanId2 = params.get("scanId2");

    if (!scanId1 || !scanId2) {
      setState((prev) => ({ ...prev, loading: false, error: "Two scans are required for comparison" }));
      return;
    }

    const fetchComparison = async () => {
      try {
        const res = await fetch("/api/scans/compare", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ scanId1, scanId2 }),
        });

        if (!res.ok) {
          const data = await res.json();
          throw new Error(data.error || "Failed to load comparison");
        }

        const data = await res.json();
        setState({
          scan1: data.scan1,
          scan2: data.scan2,
          loading: false,
          error: null,
        });
      } catch (err) {
        setState((prev) => ({
          ...prev,
          loading: false,
          error: err instanceof Error ? err.message : "Failed to load comparison",
        }));
      }
    };

    if (status === "authenticated") {
      fetchComparison();
    }
  }, [status, router]);

  const renderScan = (scan: ScanEntry | null, label: string) => {
    if (!scan) return null;

    return (
      <Card className="p-6">
        <div className="space-y-4">
          <div>
            <h3 className="text-lg font-semibold">{label}</h3>
            <p className="text-sm text-muted-foreground">
              {new Date(scan.created_at).toLocaleString()} · {scan.items_count} dishes
            </p>
            {scan.agent_summary && (
              <p className="text-sm text-muted-foreground mt-2 line-clamp-3">
                {scan.agent_summary}
              </p>
            )}
          </div>
          <div className="space-y-2">
            {scan.dishes?.map((dish, i) => (
              <div
                key={i}
                className="flex items-center gap-3 p-3 rounded-md bg-muted/50"
              >
                {dish.image_url && (
                  <Image
                    src={dish.image_url}
                    alt={dish.name}
                    width={48}
                    height={48}
                    className="w-12 h-12 rounded object-cover"
                  />
                )}
                <div className="flex-1 min-w-0">
                  <p className="font-medium truncate">{dish.name}</p>
                  <p className="text-xs text-muted-foreground line-clamp-1">
                    {dish.description || "No description"}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </Card>
    );
  };

  if (status === "loading" || state.loading) {
    return (
      <div className="min-h-screen flex flex-col">
        <header className="border-b">
          <div className="container mx-auto px-4 py-4 flex items-center justify-between">
            <h1 className="text-2xl font-bold">Compare Menus</h1>
            <Button variant="ghost" onClick={() => router.push("/history")}>
              Back to History
            </Button>
          </div>
        </header>
        <main className="flex-1 container mx-auto px-4 py-8">
          <div className="grid md:grid-cols-2 gap-6">
            {[1, 2].map((i) => (
              <Card key={i} className="p-6">
                <div className="space-y-4">
                  <div className="h-6 w-32 bg-muted rounded animate-pulse" />
                  <div className="h-4 w-48 bg-muted rounded animate-pulse" />
                  <div className="space-y-2">
                    {[1, 2, 3].map((j) => (
                      <div key={j} className="h-16 bg-muted rounded animate-pulse" />
                    ))}
                  </div>
                </div>
              </Card>
            ))}
          </div>
        </main>
      </div>
    );
  }

  if (state.error) {
    return (
      <div className="min-h-screen flex flex-col">
        <header className="border-b">
          <div className="container mx-auto px-4 py-4 flex items-center justify-between">
            <h1 className="text-2xl font-bold">Compare Menus</h1>
            <Button variant="ghost" onClick={() => router.push("/history")}>
              Back to History
            </Button>
          </div>
        </header>
        <main className="flex-1 container mx-auto px-4 py-8">
          <Card className="p-8 text-center">
            <div className="text-5xl mb-4">⚠️</div>
            <h3 className="text-xl font-semibold mb-2">Comparison Failed</h3>
            <p className="text-muted-foreground mb-4">{state.error}</p>
            <Button onClick={() => router.push("/history")}>Back to History</Button>
          </Card>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col">
      <header className="border-b">
        <div className="container mx-auto px-4 py-4 flex items-center justify-between">
          <h1 className="text-2xl font-bold">Compare Menus</h1>
          <Button variant="ghost" onClick={() => router.push("/history")}>
            Back to History
          </Button>
        </div>
      </header>

      <main className="flex-1 container mx-auto px-4 py-8">
        <div className="grid md:grid-cols-2 gap-6">
          {renderScan(state.scan1, "Menu 1")}
          {renderScan(state.scan2, "Menu 2")}
        </div>
      </main>
    </div>
  );
}
